      [L('bitta miqdor', 'одна величина', 'one amount'), L('miqdor : uning ulushi', 'величина : её части', 'amount : its shares'), L('B = 36 → 12', 'B = 36 → 12', 'B = 36 → 12')],
      [L('farq', 'разность', 'difference'), L('farq : ulushlar farqi', 'разность : разность частей', 'difference : share difference'), L('C − A = 15 → 5', 'C − A = 15 → 5', 'C − A = 15 → 5')]
